 "content": "def transform(grid):
    """Compare two repeated foreground-pattern blocks and mark missing cells."""
    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Find contiguous non-background row bands separated by fully-background rows.
    bands = []
    start = None
    for r, row in enumerate(grid):
        active = any(v != bg for v in row)
        if active and start is None:
            start = r
        elif not active and start is not None:
            bands.append((start, r))
            start = None
    if start is not None:
        bands.append((start, len(grid)))
    # Pair equal-height bands in order. Where either repeated pattern contains
    # foreground and the corresponding cell is background in the other, mark 1.
    for i in range(0, len(bands)-1, 2):
